import{_ as a,o as s,c as r,a2 as o}from"./chunks/framework.BQq6mqvm.js";const g=JSON.parse('{"title":"上传文件","description":"","frontmatter":{},"headers":[],"relativePath":"usage/upload.md","filePath":"usage/upload.md","lastUpdated":1790385461000}'),l={name:"usage/upload.md"};function d(e,t,n,i,p,c){return s(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="上传文件" tabindex="-1">上传文件 <a class="header-anchor" href="#上传文件" aria-label="Permalink to &quot;上传文件&quot;">​</a></h1><h2 id="上传步骤" tabindex="-1">上传步骤 <a class="header-anchor" href="#上传步骤" aria-label="Permalink to &quot;上传步骤&quot;">​</a></h2><ol><li>在左侧菜单点击<strong>我的文件</strong></li><li>把文件<strong>拖到页面任意位置</strong>松手（整个页面都是落点，不用对准某个框）， 或点击右上方的<strong>上传文件</strong>按钮选择文件</li><li>文件出现在屏幕<strong>右下角的上传进度浮窗</strong>里，并自动开始上传</li><li>进度条走完、状态变成<strong>已完成</strong>就上传成功了</li></ol><p>可以一次选多个文件，它们会一起排队上传。</p><h2 id="上传整个文件夹" tabindex="-1">上传整个文件夹 <a class="header-anchor" href="#上传整个文件夹" aria-label="Permalink to &quot;上传整个文件夹&quot;">​</a></h2><p>有两种方式，效果一样 —— <strong>文件夹的层级会原样保留</strong>：</p><ul><li><strong>直接拖文件夹</strong>：从系统里把整个文件夹拖进页面松手即可。 里面所有层级的文件都会传上来，并在你的目录下建出同样的文件夹结构。</li><li><strong>点「上传文件夹」按钮</strong>：在弹出的选择框里选中一个文件夹。</li></ul><p>例如拖入一个 <code>报表</code> 文件夹，里面有 <code>2026/1.xlsx</code> 和 <code>说明.txt</code>， 上传后你的目录里就会出现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>报表/</span></span>
<span class="line"><span>├── 2026/</span></span>
<span class="line"><span>│   └── 1.xlsx</span></span>
<span class="line"><span>└── 说明.txt</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">文件夹里有什么就传什么</p><p>嵌套多少层都会完整还原（最多 16 层）。同名文件夹已存在时会直接复用， 不会重复创建，也不会覆盖已有的文件。</p></div><div class="warning custom-block"><p class="custom-block-title">想传到子文件夹里，请先进入那一层</p><p>拖入的文件一律落在你<strong>当前所在</strong>的目录；整个文件夹拖进来才会保留它自己的层级。</p></div><div class="tip custom-block"><p class="custom-block-title">拖拽时页面会给出提示</p><p>开始拖动文件后，页面中间出现「松手即上传到这里」的提示框，松手就开始上传； 把文件拖出窗口则不会上传。</p></div><h2 id="上传进度浮窗" tabindex="-1">上传进度浮窗 <a class="header-anchor" href="#上传进度浮窗" aria-label="Permalink to &quot;上传进度浮窗&quot;">​</a></h2><p>上传开始后，屏幕<strong>右下角</strong>会出现一个进度浮窗，每个文件一行，实时显示：</p><ul><li>文件名（拖入文件夹时还会带上它在文件夹里的层级，如 <code>报表/2026/1.xlsx</code>）</li><li>当前状态与「已传大小 / 总大小」、实时速度、预计剩余时间</li><li>顶部还有一条<strong>总体进度</strong>，一眼看完这一批还剩多少</li></ul><p><strong>切到别的页面也照样能看到进度</strong> —— 传着文件的时候去看分享、去改个人设置都不影响， 浮窗会一直跟到传完为止。</p><p>浮窗的用法：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>点标题栏</td><td>收起 / 展开。收起后只剩一行，不挡页面内容</td></tr><tr><td>取消</td><td>停下这个文件的上传，已传的分片会被清理</td></tr><tr><td>重试</td><td>失败的任务可以重试，已传完的分片不会重传</td></tr><tr><td>清除已完成</td><td>清掉已结束的任务记录，让列表更清爽（不影响已上传的文件）</td></tr></tbody></table><p>全部传完后浮窗会<strong>自动收起</strong>成一行；但如果有文件<strong>失败</strong>，它不会自动收起 —— 失败会一直摆在眼前，直到你处理（重试或清除）。</p><div class="tip custom-block"><p class="custom-block-title">关掉浮窗也不会中断上传</p><p>浮窗只是显示，关掉页面才会中断；只要页面还开着，上传就在继续。</p></div><h2 id="上传队列的含义" tabindex="-1">上传队列的含义 <a class="header-anchor" href="#上传队列的含义" aria-label="Permalink to &quot;上传队列的含义&quot;">​</a></h2><p>每个任务会显示当前状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>校验中</td><td>正在计算文件校验值</td></tr><tr><td>上传中</td><td>正在传输分片，右侧显示速度和预计剩余时间</td></tr><tr><td>续传中</td><td>检测到之前没传完，正在接着传</td></tr><tr><td>合并中</td><td>所有分片传完，服务端正在拼合成完整文件</td></tr><tr><td>已完成</td><td>上传成功，可以点「预览」查看</td></tr><tr><td>失败</td><td>上传出错，可以点「重试」</td></tr><tr><td>已取消</td><td>被手动取消</td></tr></tbody></table><p>每个任务会显示「已传大小 / 总大小」、实时速度和预计剩余时间。</p><h2 id="大文件与断点续传" tabindex="-1">大文件与断点续传 <a class="header-anchor" href="#大文件与断点续传" aria-label="Permalink to &quot;大文件与断点续传&quot;">​</a></h2><p>大文件会自动切成多个分片并行上传，因此：</p><ul><li><strong>中途断网</strong>：恢复网络后点「重试」即可，已经传完的分片不会重传。</li><li><strong>刷新页面或关闭浏览器</strong>：重新打开「我的文件」，选择<strong>同一个文件</strong>再次上传，系统会识别出未完成的任务并接着传。</li><li><strong>服务重启</strong>：同上。</li></ul><div class="tip custom-block"><p class="custom-block-title">为什么复传同一个文件能接着传？</p><p>系统按「文件名 + 大小 + 最后修改时间」记住未完成的上传任务。只要文件没变，就会复用之前的进度。</p><p>所以请<strong>不要修改文件内容后</strong>再传，那样会被当成新文件重新开始。</p></div><p>没有传完的任务会在服务端保留 <strong>24 小时</strong>。超过后临时分片会被自动清理，此时重新上传即可。</p><h2 id="取消与清理" tabindex="-1">取消与清理 <a class="header-anchor" href="#取消与清理" aria-label="Permalink to &quot;取消与清理&quot;">​</a></h2><ul><li><strong>取消</strong>：上传中的任务可以点「取消」，已传的分片会被清理。</li><li><strong>清除已完成</strong>：队列右上角的按钮可以清掉已结束的任务记录，让列表更清爽（不影响已上传的文件）。</li></ul><h2 id="上传限制" tabindex="-1">上传限制 <a class="header-anchor" href="#上传限制" aria-label="Permalink to &quot;上传限制&quot;">​</a></h2><p>上传前会先检查，<strong>不符合要求的文件不会被上传，也不会占用服务器空间</strong>：</p><table tabindex="0"><thead><tr><th>限制</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td>单文件最大体积</td><td>500 MB</td><td>超出的文件会立即提示</td></tr><tr><td>允许的文件类型</td><td>全部</td><td>管理员可限制为指定类型</td></tr></tbody></table><p>不符合限制时会在选择文件的瞬间直接提示，不会开始上传。如果提示「该文件类型不被允许上传」，请联系管理员调整。</p><p>如果管理员临时关闭了上传功能，页面顶部会显示提示，此时无法上传。</p><h2 id="上传的文件放在哪里" tabindex="-1">上传的文件放在哪里？ <a class="header-anchor" href="#上传的文件放在哪里" aria-label="Permalink to &quot;上传的文件放在哪里？&quot;">​</a></h2><p>上传的文件会进入<strong>你自己的目录</strong>，其他人可以浏览和下载，但只有你能重命名或删除。</p><p>上传完成后可以在<strong>我的文件</strong>里找到它。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./preview">在线预览</a></li><li><a href="./files">浏览与下载</a></li></ul>`,41)])])}const u=a(l,[["render",d]]);export{g as __pageData,u as default};
